using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;using System.Drawing;
class BForm:MainForm{public string Root,Error;public bool? Choice=false;public int Affected,Confirmed;protected override string Folder(){Directory.CreateDirectory(Root);return Root;}protected override bool? ChooseBTransponders(int total,int affected){Affected=affected;return Choice;}protected override bool ConfirmImport(int n){Confirmed=n;return true;}protected override void ShowError(string message,string title){Error=message;}protected override void OnShown(EventArgs e){}}
class BTests{
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);}
 static void Pump(Task task){while(!task.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(10);}task.GetAwaiter().GetResult();}
 [STAThread]static int Main(){try{string root=Path.GetFullPath("work/b-tests-"+DateTime.Now.Ticks);Directory.CreateDirectory(root);string mock=Path.GetFullPath("work/MockB.exe");
 Check(!BTransponderSettings.Read("CountryCode=752"),"safe migration default");string setting=BTransponderSettings.With("CountryCode=752\nOverwriteBTransponders = false",true);Check(BTransponderSettings.Read(setting)&&setting.Contains("CountryCode=752"),"setting roundtrip");bool bad=false;try{BTransponderSettings.Read("OverwriteBTransponders=maybe");}catch{bad=true;}Check(bad,"invalid setting rejected");
 string before=Path.Combine(root,"preview.txt");File.WriteAllText(before,"000001\tSE-020201-1234\t?\t12345\n000002\tSE-020201-1235\t?\t0\n000003\tNO-041308-0967\t578000000000001\t98765\nZN\n");var rows=Logic.Read(before,"752",true);Check(rows[0].BKnown&&rows[0].B=="12345"&&rows[2].Status.Contains("orört"),"B hidden data and existing ISO preserved");Check(BTransponders.Select(rows,false).Count==1&&BTransponders.Select(rows,true).Count==2,"filter");bad=false;try{Logic.Import(rows);}catch{bad=true;}Check(bad,"import-level guard");Check(Logic.Import(rows,true).Contains("VN390002000001"),"explicit overwrite");
 Application.EnableVisualStyles();var flags=BindingFlags.Instance|BindingFlags.NonPublic;
 foreach(int option in new[]{0,1,2})using(var form=new BForm{Root=Path.Combine(root,"manual-"+option),Choice=option==2?(bool?)null:option==1}){
 ((TextBox)typeof(MainForm).GetField("iso",flags).GetValue(form)).Text=mock;typeof(MainForm).GetMethod("LoadFile",flags).Invoke(form,new object[]{before});form.Show();Application.DoEvents();System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());Pump((Task)typeof(MainForm).GetMethod("SendLiveCore",flags).Invoke(form,null));Check(form.Error==null,form.Error??"no manual error");Check(form.Affected==1,"affected count");string path=Path.Combine(form.Root,"writes.txt");Check(File.Exists(path)==(option!=2),"manual cancel");if(option!=2){string writes=File.ReadAllText(path);Check(writes.Contains("VN390002000001")== (option==1),"manual choice");Check(form.Confirmed==(option==1?2:1),"confirm actual selected count");}form.Close();}
 foreach(string scenario in new[]{"freshB","unknown"})using(var form=new BForm{Root=Path.Combine(root,scenario),Choice=false}){
 Directory.CreateDirectory(form.Root);File.WriteAllText(Path.Combine(form.Root,"reads.txt"),"1");
 ((TextBox)typeof(MainForm).GetField("iso",flags).GetValue(form)).Text=mock;typeof(MainForm).GetMethod("LoadFile",flags).Invoke(form,new object[]{before});form.Show();Application.DoEvents();System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());Pump((Task)typeof(MainForm).GetMethod("SendLiveCore",flags).Invoke(form,null));
 Check(!File.Exists(Path.Combine(form.Root,"writes.txt")),"fresh/unknown B must prevent writing");Check(scenario=="unknown"?form.Error!=null&&form.Error.Contains("E010"):form.Error==null,"fresh/unknown B result");form.Close();}
 using(var window=new BTransponderWindow(2,1)){window.Show();Application.DoEvents();using(var image=new Bitmap(window.Width,window.Height)){window.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save("work/manual-B-val.png");}Check(((Button)window.AcceptButton).Text=="Behåll B-transpondrar","keep default");window.Close();}
 Console.WriteLine("PASS: four-column request/parser; preserved ISO; keep/overwrite/cancel; actual standalone manual mock imports; fresh B protection; unknown B abort; settings and default; UI.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
